    if i < 0 or j < 0 or i >= len(matrix) or j >= len(matrix) or visited[i][j]:
        return 0
    visited[i][j] = True
    current_avg = (sum_vals + matrix[i][j]) / (count + 1)
    max_avg = current_avg
    for dx, dy in [(-1,0), (1,0), (0,-1), (0,1)]:
        max_avg = max(max_avg, dfs(matrix, i+dx, j+dy, visited, sum_vals + matrix[i][j], count + 1))
